const field = (key, label, control = 'text', defaultValue = '', extra = {}) => ({ key, label, control, default: defaultValue, ...extra });
const text = (key, label, defaultValue = '', extra = {}) => field(key, label, 'text', defaultValue, extra);
const textarea = (key, label, defaultValue = '', extra = {}) => field(key, label, 'textarea', defaultValue, extra);
const toggle = (key, label, defaultValue = false, extra = {}) => field(key, label, 'toggle', defaultValue, extra);
const select = (key, label, options, defaultValue, extra = {}) => field(key, label, 'select', defaultValue, { options, ...extra });
const number = (key, label, defaultValue = 0, min = 0, max = 9999, extra = {}) => field(key, label, 'number', defaultValue, { min, max, ...extra });

