export function widgetDefinition(type) { return WIDGETS[type] || { label:type, group:'Outros', icon:'◇', defaults:{title:'Novo bloco'}, fields:[text('title','Título')] }; }
export function widgetGroups() {
  const groups = {};
  for (const [type, def] of Object.entries(WIDGETS)) (groups[def.group] ||= []).push({ type, ...def });
  return groups;
}
export function createProps(type) { return JSON.parse(JSON.stringify(widgetDefinition(type).defaults || {})); }

export function registerWidget(type, definition) {
  if (!/^[a-z][a-z0-9_-]{1,63}$/.test(String(type))) throw new Error('Tipo de widget inválido.');
  if (!definition || typeof definition !== 'object' || !definition.label) throw new Error('Definição de widget inválida.');
  WIDGETS[type] = { group:'Extensões', icon:'◇', defaults:{}, fields:[], ...definition };
  return WIDGETS[type];
}

export function unregisterWidget(type) { delete WIDGETS[type]; }
